"""Generate tidewater/models/generated.py from an Avro record schema."""
import json
import sys

TYPES = {"string": "str", "long": "int", "int": "int", "double": "float", "boolean": "bool"}


def py_type(t):
    if isinstance(t, list):
        inner = [x for x in t if x != "null"][0]
        return f"Optional[{TYPES[inner]}]"
    return TYPES[t]


def main(path):
    schema = json.load(open(path))
    fields = sorted(schema["fields"], key=lambda f: ("default" in f, f["name"]))
    out = [
        "# GENERATED by tools/codegen.py from schema/readings.avsc. DO NOT EDIT.",
        "from dataclasses import dataclass",
        "from typing import Optional",
        "",
        "",
        "@dataclass(frozen=True)",
        f"class {schema['name']}:",
    ]
    for f in fields:
        line = f"    {f['name']}: {py_type(f['type'])}"
        if "default" in f:
            line += f" = {f['default']!r}".replace("None", "None")
        out.append(line)
    print("\n".join(out))


if __name__ == "__main__":
    main(sys.argv[1])
